package com.chahinaz.pos;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.*;import org.springframework.test.web.servlet.MockMvc;import org.testcontainers.junit.jupiter.*;import org.testcontainers.postgresql.PostgreSQLContainer;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@Testcontainers @SpringBootTest(properties={"POS_BOOTSTRAP_ADMIN_USERNAME=bootstrap","POS_BOOTSTRAP_ADMIN_PASSWORD=development-test-password-only"}) @AutoConfigureMockMvc class Phase7ProductionIntegrationTest{@Container static PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:16-alpine");@DynamicPropertySource static void db(DynamicPropertyRegistry p){p.add("spring.datasource.url",postgres::getJdbcUrl);p.add("spring.datasource.username",postgres::getUsername);p.add("spring.datasource.password",postgres::getPassword);}@Autowired MockMvc mvc;
 @Test void publicHealthChecksDatabaseWithoutLeakingDetails()throws Exception{mvc.perform(get("/health")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("UP")).andExpect(jsonPath("$.database").doesNotExist());}
 @Test void productionFrontendAndAssetsArePublic()throws Exception{mvc.perform(get("/")).andExpect(status().isOk()).andExpect(forwardedUrl("index.html"));mvc.perform(get("/index.html")).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.containsString("<div id=\"root\"></div>")));mvc.perform(get("/assets/index.js")).andExpect(status().isNotFound());}
 @Test void spaRouteForwardsButApiIsNeverSwallowed()throws Exception{mvc.perform(get("/sales")).andExpect(status().isOk()).andExpect(forwardedUrl("/index.html"));mvc.perform(get("/api/not-a-route")).andExpect(status().is3xxRedirection());}
}
